package io.github.jesterportfolio.hearth.features;

import io.github.jesterportfolio.hearth.session.*;
import io.github.jesterportfolio.hearth.quest.*;
import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.exploration.*;
import java.util.*;
import java.util.concurrent.*;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.event.ClickEvent;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.scheduler.BukkitTask;

/** 승인된 S4 게임 기능을 같은 개인 세션/조회/저장에 연결합니다. 실행은 기존 격리 게이트 아래입니다. */
public final class S4Features implements Listener,AutoCloseable {
    public final BetterHudAdapter anchoredHud;public final FeatureStore store;public final PersonalStorage storage;public final PaperScenes scenes;public final PaperEnderStorage ender;public final PaperCartography maps;public final PaperDevice device;public final SceneContent sceneContent;public final RecoveryLedger recovery;private final PaperRecovery recoveryPlayers;
    private final PaperSessionAdapter players;private final QuestJournal journal;private final PaperQuestAdapter quests;private final Executor owner;private final FixedHud hud=new FixedHud();private final MiniMapOverlay minimap;private final boolean overlayEnabled;private record Display(PlayerSessions.Session session,QuestJournal.View view){}private final Map<Player,Display> views=new IdentityHashMap<>();private final Map<Player,PlayerSessions.Session> ready=new IdentityHashMap<>();private final BukkitTask timer;private final Map<Player,Long> overlayNext=new IdentityHashMap<>();private boolean closed;
    public S4Features(JavaPlugin plugin,PaperSessionAdapter players,PlayerSessions sessions,FeatureStore store,PersonalStorage storage,PaperInventoryCodec codec,QuestJournal journal,PersonalQuest personal,QuestCatalog catalog,ExplorationContent content,PaperQuestAdapter quests,io.github.jesterportfolio.hearth.combat.PaperCombatPlayers combat,ServerProgressAccess access,Executor owner){
        this.players=players;this.journal=journal;this.quests=quests;this.store=store;this.storage=storage;this.owner=owner;anchoredHud=plugin.getConfig().getBoolean("betterhud-enabled")?new BetterHudAdapter(plugin,players,owner):null;overlayEnabled=plugin.getConfig().getBoolean("minimap-overlay-enabled");minimap=new MiniMapOverlay(plugin.getConfig().getInt("minimap-horizontal-offset",96));recovery=new RecoveryLedger(store);recoveryPlayers=new PaperRecovery(recovery,players,sessions,owner,(c,id)->combat!=null&&combat.knownDurable(c,id));if(combat!=null)combat.durability(new DurableCombat(recovery,access,owner));var file=new java.io.File(plugin.getDataFolder(),"cutscene-demo.yml");if(!file.exists())plugin.saveResource("cutscene-demo.yml",false);sceneContent=SceneContent.parse(YamlConfiguration.loadConfiguration(file).getValues(false),catalog);scenes=new PaperScenes(plugin,players,journal,sceneContent,store,owner);ender=new PaperEnderStorage(plugin,players,storage,codec,owner);maps=new PaperCartography(plugin,players,sessions,storage,codec,journal,content,catalog,owner);device=new PaperDevice(plugin,players,sessions,store,codec,owner,quests::showPhone);
        players.personalStorage(ender::allowed,ender::facility,ender::observe);players.boundItems(device::click,device::drag);players.features(this::command,this::ready);personal.acceptPolicy(scenes::accepted);quests.features((p,id)->{var session=players.current(p);if(session==null||scenes.accepted(session.context(),id))return false;scenes.forQuest(p,id,()->quests.showNpcQuest(p,id));return true;},this::present,this::clearDisplay);quests.featureMenu(this::menu,p->device.issue(p,true).exceptionally(error->{p.sendMessage(Component.text("스마트폰 재발급 저장 보류"));return null;}));Bukkit.getPluginManager().registerEvents(this,plugin);
        timer=Bukkit.getScheduler().runTaskTimer(plugin,()->{for(var p:Bukkit.getOnlinePlayers()){var session=players.prepared(p);if(session==null){clearDisplay(p);continue;}var cached=views.get(p);if(cached!=null&&System.currentTimeMillis()>=overlayNext.getOrDefault(p,0L)){try{if(cached.session()!=session)throw new IllegalStateException("HUD_SESSION_CHANGED");journal.requireView(session.context(),cached.view());overlay(p,session,cached.view());}catch(RuntimeException stale){clearDisplay(p);}}if(ready.get(p)!=session&&players.current(p)==session)ready(p,session);}},5,5);
    }
    private void ready(Player p,PlayerSessions.Session session){if(ready.get(p)==session)return;ready.put(p,session);players.featureLoading(p,session,true);recoveryPlayers.ready(p,session).thenComposeAsync(v->{if(players.prepared(p)!=session)throw new IllegalStateException("FEATURE_READY_STALE");players.featureLoading(p,session,false);return device.issue(p,false);},owner).whenCompleteAsync((v,error)->{if(players.linked(p)!=session)return;if(error!=null){players.featureLoading(p,session,true);players.craftingHold(session);p.sendMessage(Component.text("개인 저장/복구 확인 보류 · 원본 기록을 유지합니다."));}else if(players.current(p)==session)scenes.ready(p,session);else ready.remove(p,session);},owner);}
    public boolean command(Player p,String line){if(scenes.command(p,line)||maps.command(p,line)||ender.command(p,line))return true;if(line.equals("/hearthfeatures")){menu(p);return true;}if(line.equals("/hearthphone device")){device.issue(p,true).exceptionally(error->{p.sendMessage(Component.text("스마트폰 저장 보류 · 원본을 보존합니다."));return null;});return true;}if(line.equals("/hearthhud on")||line.equals("/hearthhud off")){var s=players.current(p);if(s!=null)journal.hud(s.context(),s,()->players.current(p)==s,line.endsWith(" on")).whenCompleteAsync((view,error)->{if(error==null&&players.current(p)==s)present(p,view);},owner);return true;}return false;}
    public void present(Player p,QuestJournal.View view){var s=players.prepared(p);if(s==null)return;journal.requireView(s.context(),view);views.put(p,new Display(s,view));maps.present(p,view);overlay(p,s,view);}
    private void overlay(Player p,PlayerSessions.Session s,QuestJournal.View view){overlayNext.put(p,System.currentTimeMillis()+2000);var lines=view.journal().preferences().hudEnabled()?journal.hudLines(view):List.<String>of();if(anchoredHud!=null){var rows=List.<List<Integer>>of();if(view.journal().preferences().minimapEnabled()){var marks=new ArrayList<HudMinimap.Mark>();var cursors=maps.markers(p,view,true);for(int i=0;i<cursors.size();i++){var c=cursors.getCursor(i);marks.add(new HudMinimap.Mark(c.getX(),c.getY(),c.getType()==org.bukkit.map.MapCursor.Type.RED_X?0xff6262:c.getType()==org.bukkit.map.MapCursor.Type.BLUE_MARKER?0x76baff:c.getType()==org.bukkit.map.MapCursor.Type.BANNER_GREEN?0x79ff96:0xffdf76));}rows=HudMinimap.frame(maps.raster(p.getWorld(),p.getLocation().getBlockX(),p.getLocation().getBlockZ(),true,view.exploration()),marks,p.getYaw(),view.journal().preferences().playerMarker(),index->org.bukkit.map.MapPalette.getColor((byte)index).getRGB()&0xffffff);}if(anchoredHud.show(p,s,lines,rows)){hud.clear(p);minimap.clear(p);return;}}if(!lines.isEmpty())hud.show(p,s,lines,()->players.prepared(p)==s);else hud.clear(p);if(overlayEnabled&&view.journal().preferences().minimapEnabled())minimap.show(p,s,maps.raster(p.getWorld(),p.getLocation().getBlockX(),p.getLocation().getBlockZ(),true,view.exploration()),maps.markers(p,view,true),view.journal().preferences().playerMarker());else minimap.clear(p);}
    public void clearDisplay(Player p){maps.forget(p);views.remove(p);overlayNext.remove(p);try{if(anchoredHud!=null)anchoredHud.clear(p);}finally{try{hud.clear(p);}finally{minimap.clear(p);}}}
    public void menu(Player p){var s=players.current(p);if(s==null)return;var lines=List.of("본인이 발견한 지형 지도와 원형 미니맵, 개인 시청 기록과 현재 목표를 확인하세요.","엔더 보관함은 해당 시설에서만 열며 다른 진행과 공유하지 않습니다.","지도 아이템은 빈 보관 칸이 있을 때 저장 후 받습니다. 스마트폰은 개인·진행 소유입니다.");var actions=new ArrayList<Component>();for(String[] action:List.of(new String[]{"지형 지도 받기/확인","/hearthmap"},new String[]{"원형 미니맵 받기/확인","/hearthmap round"},new String[]{"시설의 개인 엔더 보관함","/hearthender"},new String[]{"스마트폰 확인/재발급","/hearthphone device"},new String[]{"이어 하기","/hearthresume"}))actions.add(Component.text(action[0]).clickEvent(ClickEvent.runCommand(action[1])));for(var scene:sceneContent.scenes().values())if(journal.questAllowed(s.context(),scene.quest())){actions.add(Component.text(scene.title()+" · 장면/재도전").clickEvent(ClickEvent.runCommand("/hearthscene "+scene.id())));if(scenes.progress.completed(s.context(),scene.id()))actions.add(Component.text(scene.title()+" · 기록 재시청").clickEvent(ClickEvent.runCommand("/hearthscene "+scene.id()+" replay")));}p.openBook(PaperQuestUI.book(new QuestBookView("개인 지도·장면·보관",io.github.jesterportfolio.hearth.phone.PhonePages.text("개인 지도·장면·보관",lines).pages()),actions));}
    @EventHandler public void quit(PlayerQuitEvent e){var p=e.getPlayer();clearDisplay(p);ready.remove(p);}
    public CompletionStage<Void> barrier(UUID run){return scenes.progress.barrier(run);}
    public void close(){closed=true;timer.cancel();try{io.github.jesterportfolio.hearth.util.ShutdownCleanup.close(anchoredHud,hud,minimap,maps,scenes,ender,device);}finally{HandlerList.unregisterAll(this);views.clear();ready.clear();overlayNext.clear();}}
}
